import React, { useState, useEffect } from 'react';
import PropTypes from 'prop-types';
import './movie-list.scss';

import { SwiperSlide, Swiper } from 'swiper/react';
import tmdbApi, { category } from '../../api/tmdbApi';
import MovieCard from '../movie-card/MovieCard';

const MovieList = props => {
    const [items, setItems] = useState([]);

    useEffect(() => {
        const getList = async () => {
            // IF CUSTOM MOVIES ARE PASSED FROM HOME, USE THEM DIRECTLY INSTEAD OF FETCHING!
            if (props.movies && props.movies.length > 0) {
                setItems(props.movies);
                return;
            }

            // Otherwise, fallback to original TMDB fetching behavior for standard sections
            let response = null;
            const params = {};

            if (props.type !== 'all') {
                switch(props.category) {
                    case category.movie:
                        response = await tmdbApi.getMoviesList(props.type, {params});
                        break;
                    default:
                        response = await tmdbApi.getTvList(props.type, {params});
                }
            } else {
                response = await tmdbApi.similar(props.category, props.id);
            }
            setItems(response.results || []);
        }
        getList();
    }, [props.movies, props.category, props.type, props.id]);

    return (
        <div className="movie-list">
            <Swiper
                grabCursor={true}
                spaceBetween={10}
                slidesPerView={'auto'}
            >
                {
                    items.map((item, i) => (
                        <SwiperSlide key={i}>
                            <MovieCard category={props.category} item={item}/>
                        </SwiperSlide>
                    ))
                }
            </Swiper>
        </div>
    );
}

MovieList.propTypes = {
    category: PropTypes.string.isRequired,
    type: PropTypes.string.isRequired
}

export default MovieList;
